import{_ as i,A as e,q as a,B as t,aV as s,H as o}from"./chunks/framework.B_e8lQlv.js";const n=JSON.parse('{"title":"Standards","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/project/standard.md","filePath":"en/guide/project/standard.md"}');const l=i({name:"en/guide/project/standard.md"},[["render",function(i,n,l,r,c,h){const d=e("NolebaseGitContributors"),p=e("NolebaseGitChangelog");return a(),t("div",null,[n[0]||(n[0]=s('<h1 id="standards" tabindex="-1">Standards <a class="header-anchor" href="#standards" aria-label="Permalink to &quot;Standards&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Contributing Code</p><ul><li>If you want to contribute code to the project, please ensure your code complies with the project&#39;s coding standards.</li><li>If you are using <code>vscode</code>, you need to install the following plugins: <ul><li><a href="https://marketplace.visualstudio.com/items?itemName=dbaeumer.vscode-eslint" target="_blank" rel="noreferrer">ESLint</a> - Script code checking</li><li><a href="https://marketplace.visualstudio.com/items?itemName=oxc.oxc-vscode" target="_blank" rel="noreferrer">Oxc</a> - Oxlint / Oxfmt integration</li><li><a href="https://marketplace.visualstudio.com/items?itemName=streetsidesoftware.code-spell-checker" target="_blank" rel="noreferrer">Code Spell Checker</a> - Word syntax checking</li><li><a href="https://marketplace.visualstudio.com/items?itemName=stylelint.vscode-stylelint" target="_blank" rel="noreferrer">Stylelint</a> - CSS formatting</li></ul></li></ul></div><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Students with basic engineering literacy always pay attention to coding standards, and code style checking (Code Linting, simply called Lint) is an important means to ensure the consistency of coding standards.</p><p>Following the corresponding coding standards has the following benefits:</p><ul><li>Lower bug error rate</li><li>Efficient development efficiency</li><li>Higher readability</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>The project&#39;s configuration files are located in <code>internal/lint-configs</code>, where you can modify various lint configurations.</p><p>The project integrates the following code verification tools:</p><ul><li><a href="https://oxc.rs/docs/guide/usage/formatter.html" target="_blank" rel="noreferrer">Oxfmt</a> for code formatting</li><li><a href="https://oxc.rs/docs/guide/usage/linter.html" target="_blank" rel="noreferrer">Oxlint</a> for JavaScript / TypeScript linting</li><li><a href="https://eslint.org/" target="_blank" rel="noreferrer">ESLint</a> for Vue, JSONC, YAML, and related rules</li><li><a href="https://stylelint.io/" target="_blank" rel="noreferrer">Stylelint</a> for CSS style checking</li><li><a href="https://commitlint.js.org/" target="_blank" rel="noreferrer">Commitlint</a> for checking the standard of git commit messages</li><li><a href="https://publint.dev/" target="_blank" rel="noreferrer">Publint</a> for checking the standard of npm packages</li><li><a href="https://cspell.org/" target="_blank" rel="noreferrer">Cspell</a> for checking spelling errors</li><li><a href="https://github.com/evilmartians/lefthook" target="_blank" rel="noreferrer">lefthook</a> for managing Git hooks, automatically running code checks and formatting before commits</li></ul><h2 id="oxfmt" tabindex="-1">Oxfmt <a class="header-anchor" href="#oxfmt" aria-label="Permalink to &quot;Oxfmt&quot;">​</a></h2><p>Oxfmt is used to keep code formatting consistent across the repository.</p><h3 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxfmt</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxfmt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The root Oxfmt entry file is <code>oxfmt.config.ts</code>, and its core configuration is located in <code>internal/lint-configs/oxfmt-config</code>.</p><h2 id="oxlint" tabindex="-1">Oxlint <a class="header-anchor" href="#oxlint" aria-label="Permalink to &quot;Oxlint&quot;">​</a></h2><p>Oxlint is the primary script linting tool for the repository.</p><h3 id="command-1" tabindex="-1">Command <a class="header-anchor" href="#command-1" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxlint</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oxlint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><h3 id="configuration-1" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-1" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The core Oxlint configuration is located in <code>internal/lint-configs/oxlint-config</code>, and the root entry file is <code>oxlint.config.ts</code>.</p><h2 id="eslint" tabindex="-1">ESLint <a class="header-anchor" href="#eslint" aria-label="Permalink to &quot;ESLint&quot;">​</a></h2><p>ESLint is used to complement Vue, JSONC, YAML, and related rules.</p><h3 id="command-2" tabindex="-1">Command <a class="header-anchor" href="#command-2" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eslint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span></span></code></pre></div><h3 id="configuration-2" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-2" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The ESLint configuration file is <code>eslint.config.mjs</code>, with its core configuration located in the <code>internal/lint-configs/eslint-config</code> directory, which can be modified according to project needs.</p><h2 id="stylelint" tabindex="-1">Stylelint <a class="header-anchor" href="#stylelint" aria-label="Permalink to &quot;Stylelint&quot;">​</a></h2><p>Stylelint is used to check the style of CSS within the project. Coupled with the editor&#39;s auto-fix feature, it can effectively unify the CSS style within the project.</p><h3 id="command-3" tabindex="-1">Command <a class="header-anchor" href="#command-3" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stylelint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;**/*.{vue,css,less,scss}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache</span></span></code></pre></div><h3 id="configuration-3" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-3" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The Stylelint configuration file is <code>stylelint.config.mjs</code>, with its core configuration located in the <code>internal/lint-configs/stylelint-config</code> directory, which can be modified according to project needs.</p><h2 id="commitlint" tabindex="-1">CommitLint <a class="header-anchor" href="#commitlint" aria-label="Permalink to &quot;CommitLint&quot;">​</a></h2><p>In a team, everyone&#39;s git commit messages can vary widely, making it difficult to ensure standardization without a mechanism. You might think of using git&#39;s hook mechanism to write shell scripts to implement this. Of course, this is possible, but JavaScript has a good tool for this template: commitlint.</p><h3 id="configuration-4" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-4" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The CommitLint configuration file is <code>.commitlintrc.js</code>, with its core configuration located in the <code>internal/lint-configs/commitlint-config</code> directory, which can be modified according to project needs.</p><h3 id="git-commit-standards" tabindex="-1">Git Commit Standards <a class="header-anchor" href="#git-commit-standards" aria-label="Permalink to &quot;Git Commit Standards&quot;">​</a></h3><p>Refer to <a href="https://github.com/conventional-changelog/conventional-changelog/tree/master/packages/conventional-changelog-angular" target="_blank" rel="noreferrer">Angular</a></p><ul><li><code>feat</code> Add new features</li><li><code>fix</code> Fix problems / BUGs</li><li><code>style</code> Code style changes that do not affect the outcome</li><li><code>perf</code> Optimization / performance improvement</li><li><code>refactor</code> Refactoring</li><li><code>revert</code> Revert changes</li><li><code>test</code> Related to tests</li><li><code>docs</code> Documentation / comments</li><li><code>chore</code> Dependency updates / scaffold configuration changes</li><li><code>workflow</code> Workflow improvements</li><li><code>ci</code> Continuous integration</li><li><code>types</code> Type modifications</li></ul><h3 id="disabling-git-commit-standard-checks" tabindex="-1">Disabling Git Commit Standard Checks <a class="header-anchor" href="#disabling-git-commit-standard-checks" aria-label="Permalink to &quot;Disabling Git Commit Standard Checks&quot;">​</a></h3><p>If you want to disable Git commit standard checks, there are two ways:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-MNc4T" id="tab-Tr9HVJz" checked><label data-title="Temporary disable" for="tab-Tr9HVJz">Temporary disable</label><input type="radio" name="group-MNc4T" id="tab-0UVuc_4"><label data-title="Long-term disable" for="tab-0UVuc_4">Long-term disable</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;feat: add home page&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-verify</span></span></code></pre></div><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">commit-msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # commitlint:</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #   run: pnpm exec commitlint --edit $1</span></span></code></pre></div></div></div><p>If you changed <code>lefthook.yml</code>, reinstall hooks with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lefthook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="publint" tabindex="-1">Publint <a class="header-anchor" href="#publint" aria-label="Permalink to &quot;Publint&quot;">​</a></h2><p>Publint is a tool for checking npm package standards, including package versioning, exports, and ESM package structure.</p><h3 id="command-4" tabindex="-1">Command <a class="header-anchor" href="#command-4" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publint</span></span></code></pre></div><h2 id="cspell" tabindex="-1">Cspell <a class="header-anchor" href="#cspell" aria-label="Permalink to &quot;Cspell&quot;">​</a></h2><p>Cspell is a tool for checking spelling errors in the code, avoiding bugs caused by spelling mistakes.</p><h3 id="command-5" tabindex="-1">Command <a class="header-anchor" href="#command-5" aria-label="Permalink to &quot;Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:cspell</span></span></code></pre></div><h3 id="configuration-5" tabindex="-1">Configuration <a class="header-anchor" href="#configuration-5" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>The cspell configuration file is <code>cspell.json</code>, which can be modified according to project needs.</p><h2 id="git-hook" tabindex="-1">Git Hook <a class="header-anchor" href="#git-hook" aria-label="Permalink to &quot;Git Hook&quot;">​</a></h2><p>Git hooks are generally combined with various lints to check code style during git commits. If the check fails, the commit will not proceed. Developers need to modify and resubmit.</p><h3 id="lefthook" tabindex="-1">lefthook <a class="header-anchor" href="#lefthook" aria-label="Permalink to &quot;lefthook&quot;">​</a></h3><p>One issue is that the check would verify all code, but in practice we usually only want to check the code being committed. This is where lefthook comes in.</p><p>The most effective solution is to perform lint checks locally before committing. A common practice is to use lefthook to perform checks before local submission.</p><p>The project defines corresponding hooks inside <code>lefthook.yml</code>:</p><ul><li><code>pre-commit</code>: Runs before commit, used for code formatting and checking <ul><li><code>code-workspace</code>: Updates VSCode workspace configuration</li><li><code>lint-md</code>: Formats Markdown files</li><li><code>lint-vue</code>: Formats and checks Vue files</li><li><code>lint-js</code>: Formats and checks JavaScript / TypeScript files</li><li><code>lint-style</code>: Formats and checks style files</li><li><code>lint-package</code>: Formats <code>package.json</code></li><li><code>lint-json</code>: Formats other JSON files</li></ul></li><li><code>post-merge</code>: Runs after merge, used for automatic dependency installation <ul><li><code>install</code>: Runs <code>pnpm install</code> to install new dependencies</li></ul></li><li><code>commit-msg</code>: Runs during commit, used for checking commit message format <ul><li><code>commitlint</code>: Uses commitlint to check commit messages</li></ul></li></ul><p>Current hooks can be installed with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lefthook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h4 id="how-to-disable-lefthook" tabindex="-1">How to Disable lefthook <a class="header-anchor" href="#how-to-disable-lefthook" aria-label="Permalink to &quot;How to Disable lefthook&quot;">​</a></h4><p>If you want to temporarily disable lefthook, use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;feat: add home page&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-verify</span></span></code></pre></div><h4 id="how-to-modify-lefthook-configuration" tabindex="-1">How to Modify lefthook Configuration <a class="header-anchor" href="#how-to-modify-lefthook-configuration" aria-label="Permalink to &quot;How to Modify lefthook Configuration&quot;">​</a></h4><p>If you want to modify lefthook&#39;s configuration, you can edit the <code>lefthook.yml</code> file. For example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pre-commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  parallel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    lint-js</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pnpm oxfmt {staged_files} &amp;&amp; pnpm oxlint --fix {staged_files} &amp;&amp; pnpm eslint --cache --fix {staged_files}</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      glob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.{js,jsx,ts,tsx}&#39;</span></span></code></pre></div><p>Where:</p><ul><li><code>parallel</code>: Whether to execute tasks in parallel</li><li><code>commands</code>: Defines the list of tasks to execute</li><li><code>run</code>: Command to execute</li><li><code>glob</code>: File pattern to match</li><li><code>{staged_files}</code>: Represents the list of staged files</li></ul>',73)),o(d),o(p)])}]]);export{n as __pageData,l as default};
